import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
/* eslint-disable */

import { AddUserToTeam, ExitFromGroupchat } from "@/graphql/mutations.js";
import { edit_team_details } from "@/graphql/mutations.js";
import { delete_stichh_channel } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { change_ownership_channel } from "@/graphql/mutations.js";
import ChannelsAPIInfo from "./ChannelsAPIInfo.vue";
export default {
  props: {
    selectedChat: Object,
    allusers: Array
  },
  components: {
    ChannelsAPIInfo
  },
  mixins: [get_all_org_users],
  data() {
    return {
      allUSersNames: [],
      model: [],
      selectedUsers: [],
      selectUser: "",
      userItems: [],
      loading: false,
      groupNameEdit: false,
      groupNewOwner: false,
      loadingdelete: false,
      loadingsave: false,
      memberView: false,
      GroupName: "",
      searchQuery: "",
      tabvalue: "overview",
      listHeight: 0,
      UserDetails: [],
      filteredAllUsers: []
    };
  },
  computed: {
    filteredUsers() {
      return this.filteredAllUsers.filter(chat => {
        return chat.full_user_name.toLowerCase().includes(this.searchQuery.toLowerCase());
      });
    }
  },
  async mounted() {
    this.UserDetails = this.selectedChat;
    this.listHeight = window.innerHeight - 350;
    await this.get_all_org_users();
    this.allUSersNames = this.orgUsers;
    this.filteredAllUsers = this.orgUsers.filter(user => user.user_status === "ACTIVE");
    this.filteredAllUsers = this.filteredAllUsers.filter(user => user.user_email_id !== this.$store.getters.GetUserObj.user.user_email_id);
    this.filteredAllUsers = this.filteredAllUsers.filter(item => !this.selectedChat.restricted_users.includes(item.user_id));
    this.GroupName = this.selectedChat.team_name;
    this.userItems = [];
    // console.log("userItems", this.filteredAllUsers)
    this.filteredAllUsers.forEach(element => {
      if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT" && element.user_email_id != this.selectedChat.team_created_by) {
        this.userItems.push({
          full_user_name: element.full_user_name,
          user_email_id: element.user_email_id
        });
      }
    });
  },
  watch: {
    tabvalue() {
      this.groupNameEdit = false;
      this.memberView = false;
      this.selectedUsers = [];
    }
  },
  methods: {
    editgroup() {
      if (this.$refs.form.validate()) {
        this.edit_teams_message();
      }
    },
    editteamName() {
      this.groupNameEdit = true;
    },
    async edit_teams_message() {
      this.loadingsave = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_team_details, {
          input: {
            team_id: this.selectedChat.team_id,
            team_name: this.GroupName,
            team_description: this.GroupName
          }
        }));
        var response = JSON.parse(result.data.edit_team_details);
        this.loadingsave = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("rowupdate", 0);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loadingsave = false;
      }
    },
    async delete_teams_message() {
      this.loadingdelete = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(delete_stichh_channel, {
          input: {
            team_id: this.selectedChat.team_id,
            user_email_id: data.user.user_email_id
          }
        }));
        var response = JSON.parse(result.data.delete_stichh_channel);
        this.loadingdelete = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("rowupdate", 0);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loadingdelete = false;
      }
    },
    async exit_teams_message() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(ExitFromGroupchat, {
          input: {
            team_id: this.selectedChat.team_id
          }
        }));
        var response = JSON.parse(result.data.ExitFromGroupchat);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("successMsgexit", 0);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    },
    async create_teams_message() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      var users = this.selectedUsers.map(user => user.user_id);
      try {
        let result = await API.graphql(graphqlOperation(AddUserToTeam, {
          input: {
            team_id: this.selectedChat.team_id,
            action_type: "ADD",
            user_id: users
          }
        }));
        var response = JSON.parse(result.data.AddUserToTeam);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("rowupdate", 0);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    },
    fetch_user_name(value) {
      var name = "";
      this.allUSersNames.forEach(element => {
        if (element.user_email_id == value) {
          name = element.full_user_name;
        }
      });
      return name;
    },
    fetch_userid_name(value) {
      var name = "";
      this.allUSersNames.forEach(element => {
        if (element.user_id == value) {
          name = element.full_user_name;
        }
      });
      return name;
    },
    fetch_date(val) {
      const d = new Date(parseInt(val * 1000));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      return (+date <= 9 ? "0" + date : date) + "-" + (+month <= 9 ? "0" + month : month) + "-" + year;
    },
    saveNewOwner() {
      if (this.$refs.ownerform.validate()) {
        this.transfer_Ownership_save();
      }
    },
    async transfer_Ownership_save() {
      this.loadingsave = true;
      var data = this.$store.getters.GetUserObj;
      // console.log(this.entryInfo.responseObject.directory_id);
      try {
        let result = await API.graphql(graphqlOperation(change_ownership_channel, {
          input: {
            team_id: this.selectedChat.team_id,
            user_email_id: this.selectUser,
            organization_id: data.organization.organization_id
          }
        }));
        this.loadingsave = false;
        var response = JSON.parse(result.data.change_ownership_channel);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("rowupdate", 0);
          this.groupNewOwner = false;
        } else {
          this.$emit("errorMsg", response.Message);
          this.groupNewOwner = false;
        }
      } catch (error) {
        this.loadingsave = false;
        this.groupNewOwner = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
